"use strict";(self.webpackChunkhn_cho_sh=self.webpackChunkhn_cho_sh||[]).push([[95163],{3331:(e,n,i)=>{i.d(n,{R:()=>a,x:()=>d});var r=i(36672);const t={},s=r.createContext(t);function a(e){const n=r.useContext(s);return r.useMemo((function(){return"function"==typeof e?e(n):{...n,...e}}),[n,e])}function d(e){let n;return n=e.disableParentContext?"function"==typeof e.components?e.components(t):e.components||t:a(e.components),r.createElement(s.Provider,{value:n},e.children)}},84318:(e,n,i)=>{i.r(n),i.d(n,{assets:()=>u,contentTitle:()=>d,default:()=>o,frontMatter:()=>a,metadata:()=>r,toc:()=>l});const r=JSON.parse('{"id":"2023/04/13","title":"2023-04-13","description":"Semaphore: Eine Ganzk\xf6rper-Tastatur","source":"@site/i18n/de/docusaurus-plugin-content-docs/current/2023/04/13.md","sourceDirName":"2023/04","slug":"/2023/04/13","permalink":"/de/2023/04/13","draft":false,"unlisted":false,"editUrl":"https://github.com/anaclumos/heimdall/blob/main/i18n/de/docusaurus-plugin-content-docs//current/2023/04/13.md","tags":[],"version":"current","frontMatter":{"localized_date":"13. April 2023","top_news":"Semaphore: Eine Ganzk\xf6rper-Tastatur"},"sidebar":"defaultSidebar","previous":{"title":"2023-04-14","permalink":"/de/2023/04/14"},"next":{"title":"2023-04-12","permalink":"/de/2023/04/12"}}');var t=i(23420),s=i(3331);const a={localized_date:"13. April 2023",top_news:"Semaphore: Eine Ganzk\xf6rper-Tastatur"},d="2023-04-13",u={},l=[{value:"Semaphore: Eine Ganzk\xf6rper-Tastatur",id:"semaphore-eine-ganzk\xf6rper-tastatur",level:2},{value:"Discussion Service anzeigen: GPT-4-gest\xfctzte Websuche f\xfcr Entwickler",id:"discussion-service-anzeigen-gpt-4-gest\xfctzte-websuche-f\xfcr-entwickler",level:2},{value:"Ich ersetze meine besten Freunde durch einen LLM, der auf 500k Gruppenchat-Nachrichten trainiert wurde",id:"ich-ersetze-meine-besten-freunde-durch-einen-llm-der-auf-500k-gruppenchat-nachrichten-trainiert-wurde",level:2},{value:"NPR verl\xe4sst Twitter, nachdem es als &quot;staatsnahe Medien&quot; bezeichnet wurde",id:"npr-verl\xe4sst-twitter-nachdem-es-als-staatsnahe-medien-bezeichnet-wurde",level:2},{value:"Massenentlassungen und abwesende Chefs sorgen f\xfcr eine Moralkrise bei Meta",id:"massenentlassungen-und-abwesende-chefs-sorgen-f\xfcr-eine-moralkrise-bei-meta",level:2},{value:"Hetzner stellt ARM64-Cloud-Server vor",id:"hetzner-stellt-arm64-cloud-server-vor",level:2},{value:"Neuer NASA-Direktor schw\xf6rt Eid auf Carl Sagans &#39;Pale Blue Dot&#39; statt auf die Bibel",id:"neuer-nasa-direktor-schw\xf6rt-eid-auf-carl-sagans-pale-blue-dot-statt-auf-die-bibel",level:2},{value:"Intel Foundry Services und Arm k\xfcndigen Zusammenarbeit beim SoC-Design an",id:"intel-foundry-services-und-arm-k\xfcndigen-zusammenarbeit-beim-soc-design-an",level:2},{value:"EVE Online-Spieler nutzt obskure Regel, um den gr\xf6\xdften Raub in der Geschichte des Spiels zu begehen",id:"eve-online-spieler-nutzt-obskure-regel-um-den-gr\xf6\xdften-raub-in-der-geschichte-des-spiels-zu-begehen",level:2},{value:"Virtuelle Threads kommen in JDK 21 an und l\xe4uten eine neue \xc4ra der Gleichzeitigkeit ein",id:"virtuelle-threads-kommen-in-jdk-21-an-und-l\xe4uten-eine-neue-\xe4ra-der-gleichzeitigkeit-ein",level:2}];function h(e){const n={a:"a",h1:"h1",h2:"h2",header:"header",p:"p",...(0,s.R)(),...e.components};return(0,t.jsxs)(t.Fragment,{children:[(0,t.jsx)(n.header,{children:(0,t.jsx)(n.h1,{id:"2023-04-13",children:"2023-04-13"})}),"\n",(0,t.jsx)(n.h2,{id:"semaphore-eine-ganzk\xf6rper-tastatur",children:"Semaphore: Eine Ganzk\xf6rper-Tastatur"}),"\n",(0,t.jsxs)(n.p,{children:[(0,t.jsx)(n.a,{href:"https://github.com/everythingishacked/Semaphore",children:"Original"}),'.\nSemaphore ist eine Ganzk\xf6rper-Tastatur, die OpenCV und MediaPipe\'s Pose-Erkennung nutzt, um K\xf6rpermerkmale aus der Videoeingabe zu erkennen, relative Unterschiede zu berechnen und sie in Tasten und Befehle zu \xfcbersetzen, die \xfcber die Tastatur gesendet werden. Die prim\xe4re Eingabe ist das "Tippen" von Buchstaben, Ziffern und Symbolen \xfcber ein Flaggen-Semaphor, indem beide Arme in verschiedenen Winkeln ausgestreckt werden, mit anderen Modifikatorgesten f\xfcr Funktionen wie Shift, Backspace und Pfeiltasten. Es l\xe4uft auf dem neuesten MacOS und kann \xfcber das Terminal mit Hilfe einer benutzerdefinierten Tastaturbibliothek aufgerufen werden.']}),"\n",(0,t.jsxs)(n.p,{children:[(0,t.jsx)(n.a,{href:"http://news.ycombinator.com/item?id=35536550",children:"Discussion Service"}),".\nEin Tastatursystem namens Semaphore, das physische Gesten verwendet, hat positives Feedback von Discussion Service-Benutzern erhalten und hat Auswirkungen auf Remote-Arbeiter, die k\xf6rperliche Bet\xe4tigung und Programmierung kombinieren wollen. Die Benutzer diskutieren \xfcber die Kombination von Semaphore mit Stenografie, Musiknoten, Yoga\xfcbungen und Programmieren, und einige weisen auf das Potenzial f\xfcr mehr Effizienz durch zus\xe4tzliche Funktionen wie die automatische Vervollst\xe4ndigung hin."]}),"\n",(0,t.jsx)(n.h2,{id:"discussion-service-anzeigen-gpt-4-gest\xfctzte-websuche-f\xfcr-entwickler",children:"Discussion Service anzeigen: GPT-4-gest\xfctzte Websuche f\xfcr Entwickler"}),"\n",(0,t.jsxs)(n.p,{children:[(0,t.jsx)(n.a,{href:"https://www.phind.com",children:"Original"}),'.\nDie Website "phind.com" ist derzeit nicht zug\xe4nglich, da sie einen Sicherheitsdienst nutzt, um sich vor Online-Angriffen zu sch\xfctzen, die durch bestimmte Aktionen ausgel\xf6st werden k\xf6nnen, z. B. durch die Eingabe eines bestimmten Wortes oder Satzes, eines SQL-Befehls oder fehlerhafter Daten. Um dieses Problem zu beheben, k\xf6nnen die Nutzer eine E-Mail an den Eigent\xfcmer der Website schicken und angeben, was sie gerade taten, als die Blockierung auftrat, sowie die Cloudflare-Ray-ID, die sich unten auf der Seite befindet.']}),"\n",(0,t.jsxs)(n.p,{children:[(0,t.jsx)(n.a,{href:"http://news.ycombinator.com/item?id=35543668",children:"Discussion Service"}),".\nDie von GPT-4 betriebene Suchmaschine von Phind.com bietet pr\xe4zise Antworten auf Kodierungen und detaillierte Erkl\xe4rungen durch benutzerdefinierte Filter, und es wurden Modelle zur Umsatzbeteiligung von Inhaltsproduzenten untersucht, obwohl es Bedenken hinsichtlich der Modellierungskosten gibt; die Nutzer haben den Dienst f\xfcr seine klaren Informationen, seine Effizienz und seine wertvollen Zusatzinformationen gelobt, obwohl einige Probleme mit der Abfragegenauigkeit festgestellt wurden. Einige Nutzer haben die F\xe4higkeit von GPT-4, Probleme zu l\xf6sen, kritisiert und seine Genauigkeit und Relevanz in Frage gestellt, aber das Phind-Team hat darauf reagiert und eine neue Version mit einem Expertenmodus ver\xf6ffentlicht."]}),"\n",(0,t.jsx)(n.h2,{id:"ich-ersetze-meine-besten-freunde-durch-einen-llm-der-auf-500k-gruppenchat-nachrichten-trainiert-wurde",children:"Ich ersetze meine besten Freunde durch einen LLM, der auf 500k Gruppenchat-Nachrichten trainiert wurde"}),"\n",(0,t.jsxs)(n.p,{children:[(0,t.jsx)(n.a,{href:"https://www.izzy.co/blogs/robo-boys.html",children:"Original"}),".\nEin LLM wurde auf Izzy Millers unzensierten Gruppenchatnachrichten aus der Collegezeit trainiert, was zu besseren Unterhaltungen mit seinen besten Freunden f\xfchrte. Der Datensatz bestand aus 500.000 Nachrichten, und Miller hat ihn zur einfacheren Modellierung in Sitzungen unterteilt. Das daraus resultierende Modell generierte ganze Unterhaltungen und erfasste das kontextuelle Wesen des Gruppenchats. Der Artikel erkl\xe4rt, wie LLaMA-Gewichte mithilfe von Python-Codierung in ein mit der Transformers-Bibliothek kompatibles Format konvertiert werden k\xf6nnen, einschlie\xdflich der Bedeutung einer angemessenen Speicherplatzbereitstellung."]}),"\n",(0,t.jsxs)(n.p,{children:[(0,t.jsx)(n.a,{href:"http://news.ycombinator.com/item?id=35540154",children:"Discussion Service"}),".\nEinige Discussion Service-Benutzer \xe4u\xdfern sich besorgt \xfcber die ethischen Implikationen der Erstellung digitaler Kopien von Personen unter Verwendung pers\xf6nlicher Daten, w\xe4hrend andere argumentieren, dass die bestehenden Gesetze und der moralische/soziale Druck weiterhin gelten. Kritiker warnen vor m\xf6glichen ruchlosen Anwendungen der LLM-Technologie durch autokratische Regime oder f\xfcr profitorientierte Zwecke. \xdcber die KI-Technologie sind kontroverse Debatten entbrannt, wobei Bedenken \xfcber ihre ungepr\xfcften Auswirkungen auf die Privatsph\xe4re und eine \xfcberm\xe4\xdfige Skepsis hinsichtlich ihrer Effektivit\xe4t bestehen. Der Einsatz von KI-Chatbots und ihr Potenzial, menschliche Beziehungen zu ersetzen, wird kontrovers diskutiert, ebenso wie ethische Bedenken gegen Textvervollst\xe4ndigungstools, die die Erstellung digitaler Simulationen verlorener Angeh\xf6riger erm\xf6glichen."]}),"\n",(0,t.jsx)(n.h2,{id:"npr-verl\xe4sst-twitter-nachdem-es-als-staatsnahe-medien-bezeichnet-wurde",children:'NPR verl\xe4sst Twitter, nachdem es als "staatsnahe Medien" bezeichnet wurde'}),"\n",(0,t.jsxs)(n.p,{children:[(0,t.jsx)(n.a,{href:"https://www.wbur.org/npr/1169269161/npr-leaves-twitter-government-funded-media-label",children:"Original"}),'.\nNPR hat seine Twitter-Aktivit\xe4ten eingestellt, nachdem Twitter das Unternehmen als "staatsnahe Medien" bezeichnet hat, eine Bezeichnung, die nach Ansicht von NPR ungenau und irref\xfchrend ist. Diese Entscheidung sch\xfctzt die Glaubw\xfcrdigkeit von NPR und stellt sicher, dass das Unternehmen Journalismus ohne Negativit\xe4t produzieren kann. Elon Musk gab zu, dass er sich bei der Kennzeichnung geirrt haben k\xf6nnte und wird sie m\xf6glicherweise in "\xf6ffentlich finanziert" \xe4ndern.']}),"\n",(0,t.jsxs)(n.p,{children:[(0,t.jsx)(n.a,{href:"http://news.ycombinator.com/item?id=35539280",children:"Discussion Service"}),'.\nNPR sah sich der Kritik ausgesetzt und verlie\xdf schlie\xdflich Twitter, nachdem es aufgrund der staatlichen Finanzierung als "staatsnahe Medien" bezeichnet worden war, was zu einer Debatte \xfcber die Kriterien f\xfcr eine solche Kennzeichnung und dar\xfcber f\xfchrte, ob sie NPR als Nachrichtenorganisation mit redaktioneller Unabh\xe4ngigkeit richtig charakterisiert. Einige Discussion Service-Nutzer vermuten, dass auch andere Unternehmen, darunter die Firmen von Elon Musk, aufgrund der staatlichen Finanzierung unter diese Kategorie fallen. In den Kommentaren wird auch die komplexe Beziehung zwischen Medienunternehmen, Finanzierungsquellen und redaktioneller Unabh\xe4ngigkeit hervorgehoben, wobei einige NPR linke Voreingenommenheit vorwerfen und andere seine Transparenz und Unabh\xe4ngigkeit verteidigen.']}),"\n",(0,t.jsx)(n.h2,{id:"massenentlassungen-und-abwesende-chefs-sorgen-f\xfcr-eine-moralkrise-bei-meta",children:"Massenentlassungen und abwesende Chefs sorgen f\xfcr eine Moralkrise bei Meta"}),"\n",(0,t.jsxs)(n.p,{children:[(0,t.jsx)(n.a,{href:"https://www.nytimes.com/2023/04/12/technology/meta-layoffs-employees-management.html",children:"Original"}),".\nDie Moral bei der Facebook-Muttergesellschaft Meta ist am Boden, weil Massenentlassungen und abwesende Chefs f\xfcr Unruhe unter den Besch\xe4ftigten sorgen. Auch die Ausrichtung des Unternehmens wird von den Mitarbeitern in Frage gestellt."]}),"\n",(0,t.jsxs)(n.p,{children:[(0,t.jsx)(n.a,{href:"http://news.ycombinator.com/item?id=35537813",children:"Discussion Service"}),".\nExperten diskutieren unterschiedliche Meinungen \xfcber die Zukunft von Spitzentechnologien wie generativer KI, VR und Kryptow\xe4hrungen. W\xe4hrend einige f\xfcr spezifische Anwendungsf\xe4lle generativer KI und Fortschritte bei generativen Medien pl\xe4dieren, werden Bedenken hinsichtlich ihres Potenzials zur Automatisierung von Arbeitspl\xe4tzen der Mittelschicht und der Genauigkeit generativer KI-Modelle ge\xe4u\xdfert. Unternehmen erhoffen sich von generativer KI eine Beschleunigung des AR/VR-Technologiemarktes, und der Erfolg der Ger\xe4te von Meta Labs wird dem ungewissen Erfolg des Apple-Headsets gegen\xfcbergestellt. Die Kryptoindustrie wird von einigen als Affinit\xe4tsbetrug betrachtet, aber Bitcoin wird von anderen immer noch anders gesehen."]}),"\n",(0,t.jsx)(n.h2,{id:"hetzner-stellt-arm64-cloud-server-vor",children:"Hetzner stellt ARM64-Cloud-Server vor"}),"\n",(0,t.jsxs)(n.p,{children:[(0,t.jsx)(n.a,{href:"https://www.hetzner.com/press-release/arm64-cloud/",children:"Original"}),".\nDer deutsche Hosting- und Cloud-Anbieter Hetzner hat vier neue Hetzner-Cloud-Server auf Basis der Arm64-Technologie auf den Markt gebracht und setzt damit erstmals auf diese Prozessoren. Die Server bieten bis zu 16 vCPUs und werden mit bis zu 32 GB ECC-RAM und bis zu 320 GB NVMe-SSD-basiertem Speicher kombiniert. Die neue Serverreihe beginnt bei einem Preis von 3,79 \u20ac (4,54 $) pro Monat und bietet stundenweise Abrechnungsoptionen, die die Kosten f\xfcr Kunden senken."]}),"\n",(0,t.jsxs)(n.p,{children:[(0,t.jsx)(n.a,{href:"http://news.ycombinator.com/item?id=35540084",children:"Discussion Service"}),".\nHetzner hat ARM64-Cloud-Server auf den Markt gebracht, die preiswerter sind und die Leistung von AWS \xfcbertreffen. Die Meinungen \xfcber Cloud-Infrastrukturen sind geteilt, da einige f\xfcr Zuverl\xe4ssigkeit und Skalierbarkeit pl\xe4dieren, w\xe4hrend andere einfachere Setups f\xfcr zuverl\xe4ssiger und kosteng\xfcnstiger halten. Das Angebot von Hetzner f\xfcllt eine L\xfccke f\xfcr diejenigen, die Docker betreiben wollen, ohne alle Dienste konfigurieren zu m\xfcssen, aber es ist m\xf6glicherweise nicht f\xfcr sicherheitsbewusste Unternehmen geeignet, da die physische Zugangskontrolle schw\xe4cher ist. Einige haben von Kontosperren aufgrund der strengen Betrugsrichtlinien von Hetzner berichtet, und es gibt Fragen zur Nachhaltigkeit der niedrigen Preise in Europa aufgrund der hohen Energiekosten."]}),"\n",(0,t.jsx)(n.h2,{id:"neuer-nasa-direktor-schw\xf6rt-eid-auf-carl-sagans-pale-blue-dot-statt-auf-die-bibel",children:"Neuer NASA-Direktor schw\xf6rt Eid auf Carl Sagans 'Pale Blue Dot' statt auf die Bibel"}),"\n",(0,t.jsxs)(n.p,{children:[(0,t.jsx)(n.a,{href:"https://www.independent.co.uk/space/nasa-director-carl-sagan-oath-b2317698.html",children:"Original"}),'.\nMakenzie Lystrup, die neu ernannte Direktorin des Goddard Space Flight Center der NASA, hat einen unkonventionellen Eid auf Carl Sagans Buch "Pale Blue Dot" aus dem Jahr 1994 anstelle der Bibel abgelegt. Das Buch des Astronomen wurde durch das ber\xfchmte Foto des blassblauen Punktes auf der Erde inspiriert, das 1990 von der Raumsonde Voyager 1 aufgenommen wurde, und Lystrup behauptet, dass er sich "sehr darauf konzentriert, die n\xe4chste Generation von Innovatoren heranzuziehen". Das Goddard Space Flight Center besch\xe4ftigt 10.000 Mitarbeiter, sowohl Beamte als auch Auftragnehmer, und ist f\xfcr die Ausf\xfchrung eines 4-Milliarden-Dollar-Portfolios verantwortlich.']}),"\n",(0,t.jsxs)(n.p,{children:[(0,t.jsx)(n.a,{href:"http://news.ycombinator.com/item?id=35536612",children:"Discussion Service"}),'.\nDer neue NASA-Direktor wurde auf Carl Sagans "Pale Blue Dot" vereidigt, was eine Debatte \xfcber die Wirksamkeit von Eiden, die Bedeutung heiliger Texte, pers\xf6nliche Werte im Vergleich zu religi\xf6sen Texten und die wahre Bedeutung der pers\xf6nlichen Verantwortung ausl\xf6ste. Einige argumentieren, dass ein Schwur auf ein Buch, das die eigenen Werte repr\xe4sentiert, angemessener ist, w\xe4hrend andere die Darstellung einer Gottheit als B\xfcrge f\xfcr den Eid f\xfcr notwendig halten. Die Vereidigung hat eine rituelle Funktion und wurde verwendet, um Gesellschaften und die Geschichte zu formen, aber letztendlich enth\xe4lt der Artikel keine neuen oder aufregenden Informationen f\xfcr Experten auf diesem Gebiet.']}),"\n",(0,t.jsx)(n.h2,{id:"intel-foundry-services-und-arm-k\xfcndigen-zusammenarbeit-beim-soc-design-an",children:"Intel Foundry Services und Arm k\xfcndigen Zusammenarbeit beim SoC-Design an"}),"\n",(0,t.jsxs)(n.p,{children:[(0,t.jsx)(n.a,{href:"https://www.intel.com/content/www/us/en/newsroom/news/intel-foundry-arm-announce-multigeneration-collaboration-leading-edge-soc-design.html",children:"Original"}),".\nIntel Foundry Services (IFS) und Arm haben eine Zusammenarbeit \xfcber mehrere Generationen hinweg vereinbart, um die Entwicklung von System-on-Chips (SoCs) mit niedrigem Stromverbrauch f\xfcr mobile Ger\xe4te und andere Branchen zu erm\xf6glichen. Im Rahmen der Zusammenarbeit werden die sicheren und energieeffizienten Prozessoren von Arm mit den Fertigungskapazit\xe4ten von IFS in den USA und der EU kombiniert, um neue, bahnbrechende Transistortechnologien f\xfcr eine verbesserte Energie- und Leistungsaufnahme auf dem Intel 18A-Prozess zu liefern. Diese Zusammenarbeit wird eine ausgewogenere globale Lieferkette f\xfcr Foundry-Kunden erm\xf6glichen, die an der Entwicklung mobiler SoCs mit Arm-basierten CPU-Kernen arbeiten."]}),"\n",(0,t.jsxs)(n.p,{children:[(0,t.jsx)(n.a,{href:"http://news.ycombinator.com/item?id=35539057",children:"Discussion Service"}),".\nIntel Foundry Services arbeitet bei der Entwicklung von SoCs mit Arm zusammen und steht damit im Wettbewerb mit TSMC, das schon l\xe4nger mit Arm zusammenarbeitet. Discussion Service-Benutzer diskutieren die Vor- und Nachteile des Mac Studio und vergleichen es mit anderen PC-Optionen, wobei sie die Einschr\xe4nkungen des Macs bei Spielen und CAD-Software kritisieren. Der Artikel und die Kommentare befassen sich mit Alternativen f\xfcr IOT-Ger\xe4te und die Fertigung, Intels 2nm-Knotenproduktion und Spekulationen \xfcber Intels F\xe4higkeit, seine Versprechen zu halten, wobei auch die Bedeutung von Stromverbrauch, Preis und Wireless-F\xe4higkeit bei der Entwicklung von IOT-Ger\xe4ten anerkannt wird."]}),"\n",(0,t.jsx)(n.h2,{id:"eve-online-spieler-nutzt-obskure-regel-um-den-gr\xf6\xdften-raub-in-der-geschichte-des-spiels-zu-begehen",children:"EVE Online-Spieler nutzt obskure Regel, um den gr\xf6\xdften Raub in der Geschichte des Spiels zu begehen"}),"\n",(0,t.jsxs)(n.p,{children:[(0,t.jsx)(n.a,{href:"https://www.pcgamer.com/eve-online-player-uses-obscure-rule-to-pull-off-the-biggest-heist-in-the-games-history/",children:"Original"}),'.\nEin EVE Online-Spieler hat den gr\xf6\xdften Raub in der Geschichte des Spiels durchgef\xfchrt, indem er die "Aktien-Mechanik" ausgenutzt hat, was zu einer Beute von \xfcber 22.300 Dollar in echtem Geld f\xfchrte. Dabei \xfcbernahm er die Kontrolle \xfcber Event Horizon Expeditionaries mit einem sauberen Account, transferierte Anteile und nahm dem Unternehmen 130 Milliarden ISK und mehrere Schiffe ab, wobei der Gesamtwert der Beute auf 2,23 Billionen ISK gesch\xe4tzt wird. Einem Reddit-Thread aus dem Jahr 2014 zufolge ist das Aktiensystem potenziell zu leicht auszunutzen, und diese Strategie wurde bereits getestet.']}),"\n",(0,t.jsxs)(n.p,{children:[(0,t.jsx)(n.a,{href:"http://news.ycombinator.com/item?id=35533711",children:"Discussion Service"}),".\nEin Spieler hat einen erfolgreichen Raub\xfcberfall in EVE Online inszeniert, was Fragen \xfcber die Unternehmensmechanik und die Ausbeutungsrisiken des Spiels aufwirft. Der Raub\xfcberfall wurde als cool und als ein Highlight des Spiels angesehen, aber einige kritisieren den finanziellen Fokus und die Mechanismen des Spiels, einschlie\xdflich des Wertes der Spielw\xe4hrung und des Unternehmenswahlsystems."]}),"\n",(0,t.jsx)(n.h2,{id:"virtuelle-threads-kommen-in-jdk-21-an-und-l\xe4uten-eine-neue-\xe4ra-der-gleichzeitigkeit-ein",children:"Virtuelle Threads kommen in JDK 21 an und l\xe4uten eine neue \xc4ra der Gleichzeitigkeit ein"}),"\n",(0,t.jsxs)(n.p,{children:[(0,t.jsx)(n.a,{href:"https://www.infoq.com/news/2023/04/virtual-threads-arrives-jdk21/",children:"Original"}),".\nN/A."]}),"\n",(0,t.jsxs)(n.p,{children:[(0,t.jsx)(n.a,{href:"http://news.ycombinator.com/item?id=35535906",children:"Discussion Service"}),".\nDie virtuellen Threads von JDK 21 reduzieren physische Threads f\xfcr die Gleichzeitigkeit und Vereinfachung von io-intensiven Anwendungen, aber es entstehen Debatten \xfcber die Speicherverwaltung. Java wird mit Go verglichen, und Frameworks wie Spring, Spring Boot und Quarkus bieten Alternativen zu Ruby on Rails, w\xe4hrend die Debatte \xfcber Java gegen\xfcber Go die Leistung, Beobachtbarkeit, Solidit\xe4t von Typsystemen und Interop ber\xfccksichtigt. Der Artikel befasst sich mit der Nischenkategorie JVM und damit, wie sich unterschiedliche Implementierungen auf die Benutzererfahrung auswirken k\xf6nnen, wobei Vergleiche mit C# und JetBrains Rider erw\xe4hnt werden."]})]})}function o(e={}){const{wrapper:n}={...(0,s.R)(),...e.components};return n?(0,t.jsx)(n,{...e,children:(0,t.jsx)(h,{...e})}):h(e)}}}]);